style.css:
@-moz-document domain("roblox.com") {
body {
        background: url("https://i.imgur.com/IZWr7Ld.jpeg") repeat !important;
        background-size: cover !important;
        color: black !important;
    }

    /* Friend cards background */
    .friend-card, 
    .profile-card,
    .avatar-card,
    .game-card,
    .avatar-card-container,
    .connection-name {
        background-color: #ffb3b3 !important; /* soft light red */
        color: black !important;
    }

    /* Friend name text */
    .connection-name, 
    .avatar-name, 
    .profile-name {
        color: black !important;
        text-shadow: none !important;
    }

    /* Hover effect for friends */
    .friend-card:hover, 
    .avatar-card:hover {
        background-color: #ff9999 !important; /* slightly deeper soft red */
    }

    /* General text */
    * {
        color: black !important;
    }

    /* Buttons */
    button, .btn {
        background-color: #ff9999 !important;
        color: black !important;
        border-radius: 8px !important;
        border: none !important;
    }
    button:hover, .btn:hover {
        background-color: #ff6666 !important;
        color: white !important;
    }
}
